# Let's try to solve the Social Golfers problem (9-3-7)
# 27 golfers, 9 groups of 3, 7 weeks
# No pair of golfers in same group more than once

from itertools import combinations

# Try using pysat or z3
try:
    import z3
    print("z3 available")
except:
    print("z3 not available")

try:
    from pysat.solvers import Glucose3
    print("pysat available")
except:
    print("pysat not available")

try:
    import pycosat
    print("pycosat available")
except:
    print("pycosat not available")

# Rebuild everything in one cell

def point_to_idx(p):
    return p[0] * 9 + p[1] * 3 + p[2]

def idx_to_point(i):
    return (i // 9, (i // 3) % 3, i % 3)

# Generate all 27 points
points = [(a, b, c) for a in range(3) for b in range(3) for c in range(3)]

def normalize_direction(d):
    for i in range(3):
        if d[i] != 0:
            inv = d[i]  # In GF(3): 1^-1=1, 2^-1=2
            return tuple((d[j] * inv) % 3 for j in range(3))
    return None

directions = set()
for a in range(3):
    for b in range(3):
        for c in range(3):
            if (a, b, c) != (0, 0, 0):
                d = normalize_direction((a, b, c))
                directions.add(d)

print(f"Number of directions: {len(directions)}")

def get_parallel_class(direction):
    used = set()
    groups = []

    for start_idx in range(27):
        if start_idx in used:
            continue
        start = idx_to_point(start_idx)
        line = []
        for t in range(3):
            p = tuple((start[i] + t * direction[i]) % 3 for i in range(3))
            line.append(point_to_idx(p))
        line.sort()
        if line[0] not in used:
            groups.append(line)
            for p in line:
                used.add(p)

    return groups

# Generate all 13 parallel classes
parallel_classes = []
for d in sorted(directions):
    pc = get_parallel_class(d)
    parallel_classes.append((d, pc))

# Verify each parallel class
for d, pc in parallel_classes:
    assert len(pc) == 9, f"Expected 9 groups, got {len(pc)}"
    all_golfers = sorted([g for group in pc for g in group])
    assert all_golfers == list(range(27)), f"Not a valid partition"

print("All 13 parallel classes verified!")

# Now verify that any two parallel classes have no repeated pairs
def get_pairs_from_class(pc):
    pairs = set()
    for group in pc:
        for i in range(len(group)):
            for j in range(i+1, len(group)):
                pairs.add(frozenset([group[i], group[j]]))
    return pairs

# Check all pairs of parallel classes
all_ok = True
for i in range(len(parallel_classes)):
    for j in range(i+1, len(parallel_classes)):
        pairs_i = get_pairs_from_class(parallel_classes[i][1])
        pairs_j = get_pairs_from_class(parallel_classes[j][1])
        overlap = pairs_i & pairs_j
        if overlap:
            print(f"Classes {i} and {j} share pairs: {overlap}")
            all_ok = False

if all_ok:
    print("All pairs of parallel classes are disjoint - perfect!")
    print(f"\nWe have {len(parallel_classes)} parallel classes, need 7")

# Complete self-contained solution

def point_to_idx(p):
    return p[0] * 9 + p[1] * 3 + p[2]

def idx_to_point(i):
    return (i // 9, (i // 3) % 3, i % 3)

def normalize_direction(d):
    for i in range(3):
        if d[i] != 0:
            inv = d[i]  # In GF(3): 1^-1=1, 2^-1=2
            return tuple((d[j] * inv) % 3 for j in range(3))
    return None

directions = set()
for a in range(3):
    for b in range(3):
        for c in range(3):
            if (a, b, c) != (0, 0, 0):
                d = normalize_direction((a, b, c))
                directions.add(d)

def get_parallel_class(direction):
    used = set()
    groups = []
    for start_idx in range(27):
        if start_idx in used:
            continue
        start = idx_to_point(start_idx)
        line = []
        for t in range(3):
            p = tuple((start[i] + t * direction[i]) % 3 for i in range(3))
            line.append(point_to_idx(p))
        line.sort()
        if line[0] not in used:
            groups.append(line)
            for p in line:
                used.add(p)
    return groups

parallel_classes = []
for d in sorted(directions):
    pc = get_parallel_class(d)
    parallel_classes.append((d, pc))

W = 7
N = 27

solution = [0] * (W * N)

for w in range(W):
    d, pc = parallel_classes[w]
    for g_idx, group in enumerate(pc):
        for golfer in group:
            solution[w * N + golfer] = g_idx

# Verify the solution
print("Verifying solution...")

# Check 1: Each week, each golfer is in exactly one group
for w in range(W):
    groups = [[] for _ in range(9)]
    for p in range(N):
        g = solution[w * N + p]
        groups[g].append(p)
    for g_idx, group in enumerate(groups):
        assert len(group) == 3, f"Week {w}, group {g_idx} has {len(group)} golfers"

print("Check 1 passed: Each week has 9 groups of 3")

# Check 2: No pair appears in same group more than once
pair_count = {}
for w in range(W):
    groups = [[] for _ in range(9)]
    for p in range(N):
        g = solution[w * N + p]
        groups[g].append(p)
    for group in groups:
        for i in range(len(group)):
            for j in range(i+1, len(group)):
                pair = (min(group[i], group[j]), max(group[i], group[j]))
                pair_count[pair] = pair_count.get(pair, 0) + 1

max_pair = max(pair_count.values())
print(f"Check 2: Maximum times any pair appears together: {max_pair}")
assert max_pair == 1, "Some pair appears more than once!"
print("Check 2 passed: No pair appears more than once!")

print(f"\nTotal pairs used: {len(pair_count)} out of {27*26//2} possible")
print(f"\nSolution length: {len(solution)}")
print("\nFull solution:")
print(solution)

# Print schedule nicely
print("\nSchedule:")
